pub type TAG = tag;
#[repr(C)]

pub struct tag {
    rawName: RawNameStorage,
    pub rawNameLength: ::core::ffi::c_int,
    pub name: TAG_NAME,
    // The tag name's converted and raw forms occupy this Rust-owned byte
    // buffer.  Its opaque backing token preserves the configured allocator's
    // malloc/realloc/free sequence without retaining a dereferenceable C
    // allocation pointer in parser state.
    buffer: TagBufferStorage,
    // Tag-local namespace bindings are owned by the parser's active binding
    // arena.  Keep its stable ID rather than an interior pointer into that
    // arena: the arena may grow or swap-remove entries while tags remain
    // active.
    bindings: Option<BindingId>,
}

// A raw tag name must remain comparable after parsing an internal entity or
// after a callback grows the input buffer.  Keep a checked owner-relative
// location until `storeRawNames` moves it into the tag buffer.
#[derive(Copy, Clone)]
enum RawNameStorage {
    Unset,
    InputBuffer(usize),
    EntityText {
        text: EntityTextRef,
        length: ::core::ffi::c_int,
        offset: usize,
    },
    TagBuffer(usize),
}

enum RawNameSource<'a> {
    Bytes(&'a [u8]),
    Chars(&'a [::core::ffi::c_char]),
}

impl RawNameSource<'_> {
    fn len(&self) -> usize {
        match self {
            Self::Bytes(bytes) => bytes.len(),
            Self::Chars(chars) => chars.len(),
        }
    }

    /// Returns the byte-preserving character view used by tokenizer scanners.
    /// `c_char` and `u8` are both one byte, and entity text is XML data rather
    /// than UTF-8 Rust text, so the byte-backed input can be viewed directly.
    fn chars(&self) -> &[::core::ffi::c_char] {
        match self {
            Self::Bytes(bytes) => bytemuck::cast_slice(bytes),
            Self::Chars(chars) => chars,
        }
    }

    /// Narrows this already-validated event window by two cursors known to
    /// refer to it.  This is deliberately address-based rather than pointer
    /// arithmetic: callers retain the owning slice and reject ranges outside
    /// it before a tokenizer helper observes them.
    fn chars_between(
        &self,
        start: usize,
        end: usize,
    ) -> Option<&[::core::ffi::c_char]> {
        let chars = self.chars();
        let base = chars.as_ptr().addr();
        let start = start.checked_sub(base)?;
        let end = end.checked_sub(base)?;
        chars.get(start..end)
    }

    /// Returns the byte-preserving view used by the tokenizer's conversion
    /// routines.  This keeps conversion callers from recreating a slice from
    /// a pair of C cursors after the owning parser/entity storage has already
    /// validated the token range.
    fn bytes(&self) -> &[u8] {
        match self {
            Self::Bytes(bytes) => bytes,
            Self::Chars(chars) => bytemuck::cast_slice(chars),
        }
    }

    fn same_bytes(&self, other: &Self) -> bool {
        self.len() == other.len()
            && match (self, other) {
                (Self::Bytes(left), Self::Bytes(right)) => left == right,
                (Self::Bytes(left), Self::Chars(right)) => left
                    .iter()
                    .zip(right.iter())
                    .all(|(&left, &right)| left == right as u8),
                (Self::Chars(left), Self::Bytes(right)) => left
                    .iter()
                    .zip(right.iter())
                    .all(|(&left, &right)| left as u8 == right),
                (Self::Chars(left), Self::Chars(right)) => left == right,
            }
    }

    fn copy_into(&self, destination: &mut [::core::ffi::c_char]) -> bool {
        if self.len() != destination.len() {
            return false;
        }
        match self {
            Self::Bytes(bytes) => {
                for (destination, &source) in destination.iter_mut().zip(bytes.iter()) {
                    *destination = source as ::core::ffi::c_char;
                }
            }
            Self::Chars(chars) => destination.copy_from_slice(chars),
        }
        true
    }

    fn decode_char_ref(
        &self,
        decoder: crate::src::xmltok::CharRefNumberDecoder,
    ) -> ::core::ffi::c_int {
        match self {
            Self::Bytes(bytes) => decoder.decode(bytes),
            Self::Chars(chars) => decoder.decode_chars(chars),
        }
    }
}

struct TagBufferStorage {
    bytes: Vec<::core::ffi::c_char>,
    backing: Option<Box<dyn FnMut(TagBufferAllocationAction) -> bool>>,
}

enum TagBufferAllocationAction {
    Grow {
        size: crate::__stddef_size_t_h::size_t,
        source_line: ::core::ffi::c_int,
    },
    Free(::core::ffi::c_int),
}

impl TagBufferStorage {
    fn empty() -> Self {
        Self {
            bytes: Vec::new(),
            backing: None,
        }
    }

    fn allocate(
        capacity: usize,
        source_line: ::core::ffi::c_int,
        mut backing: Box<dyn FnMut(TagBufferAllocationAction) -> bool>,
    ) -> Option<Self> {
        let mut bytes = Vec::new();
        if bytes.try_reserve_exact(capacity).is_err() {
            backing(TagBufferAllocationAction::Free(source_line));
            return None;
        }
        bytes.resize(capacity, 0);
        Some(Self {
            bytes,
            backing: Some(backing),
        })
    }

    fn grow(&mut self, capacity: usize, source_line: ::core::ffi::c_int) -> bool {
        if capacity <= self.bytes.len() {
            return true;
        }
        if self
            .bytes
            .try_reserve_exact(capacity - self.bytes.len())
            .is_err()
        {
            return false;
        }
        let Some(backing) = self.backing.as_mut() else {
            return false;
        };
        if !backing(TagBufferAllocationAction::Grow {
            size: capacity,
            source_line,
        }) {
            return false;
        }
        self.bytes.resize(capacity, 0);
        true
    }

    fn release(&mut self, source_line: ::core::ffi::c_int) {
        if let Some(backing) = self.backing.as_mut() {
            backing(TagBufferAllocationAction::Free(source_line));
        }
        self.backing = None;
        self.bytes = Vec::new();
    }
}

/// Converts a tokenizer-validated element name into its tag-owned UTF-8
/// buffer.  The input range is resolved through its owning parser/entity
/// storage before this helper is called, and the final buffer byte remains
/// reserved for the NUL terminator expected by callbacks.
fn convert_element_name_to_tag_buffer(
    encoding: &crate::src::xmltok::ENCODING,
    unknown_encoding: Option<&crate::src::xmltok::unknown_encoding>,
    source: RawNameSource<'_>,
    buffer: &mut TagBufferStorage,
) -> Result<::core::ffi::c_int, crate::expat_h::XML_Error> {
    let input: &[u8] = match source {
        RawNameSource::Bytes(bytes) => bytes,
        RawNameSource::Chars(chars) => bytemuck::cast_slice(chars),
    };
    let mut input_offset = 0usize;
    let mut output_offset = 0usize;

    loop {
        let output_end = buffer
            .bytes
            .len()
            .checked_sub(1)
            .ok_or(crate::expat_h::XML_ERROR_NO_MEMORY)?;
        let output = buffer
            .bytes
            .get_mut(output_offset..output_end)
            .ok_or(crate::expat_h::XML_ERROR_UNEXPECTED_STATE)?;
        let (result, consumed, written) = crate::src::xmltok::convert_to_utf8_slice(
            encoding,
            unknown_encoding,
            input
                .get(input_offset..)
                .ok_or(crate::expat_h::XML_ERROR_UNEXPECTED_STATE)?,
            bytemuck::cast_slice_mut(output),
        );
        input_offset = input_offset
            .checked_add(consumed)
            .ok_or(crate::expat_h::XML_ERROR_UNEXPECTED_STATE)?;
        output_offset = output_offset
            .checked_add(written)
            .ok_or(crate::expat_h::XML_ERROR_NO_MEMORY)?;

        if input_offset == input.len()
            || result == crate::src::xmltok::XML_CONVERT_INPUT_INCOMPLETE
        {
            return ::core::ffi::c_int::try_from(output_offset)
                .map_err(|_| crate::expat_h::XML_ERROR_NO_MEMORY);
        }
        let maximum_half_capacity = usize::try_from(crate::stdlib::SIZE_MAX / 2)
            .unwrap_or(usize::MAX);
        if buffer.bytes.len() > maximum_half_capacity {
            return Err(crate::expat_h::XML_ERROR_NO_MEMORY);
        }
        let next_capacity = buffer.bytes.len() * 2;
        if !buffer.grow(next_capacity, 3514 as ::core::ffi::c_int) {
            return Err(crate::expat_h::XML_ERROR_NO_MEMORY);
        }
    }
}

struct TagStorage {
    // A one-element vector gives this tag stable Rust-owned storage while
    // allowing allocation failure to be reported instead of aborting.
    tag: Vec<TAG>,
    // This token represents the original configured-allocator allocation for
    // the tag.  It is never dereferenced, but preserves allocation accounting
    // and custom allocator observability.
    backing: Option<Box<dyn FnMut(::core::ffi::c_int)>>,
}

struct FreeTagList {
    tags: Vec<TagStorage>,
}

impl FreeTagList {
    const fn empty() -> Self {
        Self { tags: Vec::new() }
    }
}

struct BindingStorage {
    // A one-element vector supplies a stable address to the legacy binding
    // chains without placing that address in parser state.
    binding: Vec<BINDING>,
    id: BindingId,
    // URI contents are Rust-owned.  The opaque callback below preserves the
    // configured allocator's allocation/reallocation/free sequence.
    uri: Vec<crate::expat_external_h::XML_Char>,
    binding_backing: Option<Box<dyn FnMut(::core::ffi::c_int)>>,
    uri_backing: Option<Box<dyn FnMut(BindingUriAllocationAction) -> bool>>,
}

enum BindingUriAllocationAction {
    Grow {
        size: crate::__stddef_size_t_h::size_t,
        source_line: ::core::ffi::c_int,
    },
    Replace {
        size: crate::__stddef_size_t_h::size_t,
        allocation_source_line: ::core::ffi::c_int,
        free_source_line: ::core::ffi::c_int,
    },
    Free(::core::ffi::c_int),
}

struct FreeBindingList {
    bindings: Vec<BindingStorage>,
}

impl FreeBindingList {
    const fn empty() -> Self {
        Self {
            bindings: Vec::new(),
        }
    }
}

// The allocator token factory is the sole place that retains the parser
// handle needed for Expat's observable allocation callbacks.  Once these
// tokens have been made, binding storage itself is ordinary owned Rust state.
struct BindingStorageBacking {
    binding: Box<dyn FnMut(::core::ffi::c_int)>,
    uri: Box<dyn FnMut(BindingUriAllocationAction) -> bool>,
}

impl BindingStorageBacking {
    fn release(mut self, source_line: ::core::ffi::c_int) {
        (self.uri)(BindingUriAllocationAction::Free(source_line));
        (self.binding)(source_line);
    }
}

impl BindingStorage {
    fn new(uri_capacity: usize, mut backing: BindingStorageBacking) -> Option<Self> {
        let mut binding = Vec::new();
        let mut uri = Vec::new();
        if binding.try_reserve_exact(1).is_err() || uri.try_reserve_exact(uri_capacity).is_err() {
            backing.release(4545 as ::core::ffi::c_int);
            return None;
        }
        uri.resize(uri_capacity, 0);
        binding.push(BINDING {
            prefix: BindingPrefix::Default,
            nextTagBinding: None,
            prevPrefixBinding: None,
            attId: None,
            uriLen: 0,
            uriAlloc: uri_capacity as ::core::ffi::c_int,
        });
        Some(Self {
            binding,
            id: BindingId(0),
            uri,
            binding_backing: Some(backing.binding),
            uri_backing: Some(backing.uri),
        })
    }

    fn binding_mut(&mut self) -> &mut BINDING {
        self.binding
            .first_mut()
            .expect("binding storage has one binding")
    }

    fn grow_uri(&mut self, capacity: usize, source_line: ::core::ffi::c_int) -> bool {
        if capacity <= self.uri.len() {
            return true;
        }
        if self
            .uri
            .try_reserve_exact(capacity - self.uri.len())
            .is_err()
        {
            return false;
        }
        let Some(uri_backing) = self.uri_backing.as_mut() else {
            return false;
        };
        let Some(size) =
            capacity.checked_mul(::core::mem::size_of::<crate::expat_external_h::XML_Char>())
        else {
            return false;
        };
        if !uri_backing(BindingUriAllocationAction::Grow { size, source_line }) {
            return false;
        }
        self.uri.resize(capacity, 0);
        let binding = self.binding_mut();
        binding.uriAlloc = capacity as ::core::ffi::c_int;
        true
    }

    fn release(mut self) {
        if let Some(uri_backing) = self.uri_backing.as_mut() {
            uri_backing(BindingUriAllocationAction::Free(1919 as ::core::ffi::c_int));
        }
        self.uri_backing = None;
        if let Some(binding_backing) = self.binding_backing.as_mut() {
            binding_backing(1920 as ::core::ffi::c_int);
        }
        self.binding_backing = None;
    }

    fn replace_uri(
        &mut self,
        capacity: usize,
        allocation_source_line: ::core::ffi::c_int,
        free_source_line: ::core::ffi::c_int,
    ) -> bool {
        if capacity <= self.uri.len() {
            return true;
        }
        if self
            .uri
            .try_reserve_exact(capacity - self.uri.len())
            .is_err()
        {
            return false;
        }
        let Some(uri_backing) = self.uri_backing.as_mut() else {
            return false;
        };
        let Some(size) =
            capacity.checked_mul(::core::mem::size_of::<crate::expat_external_h::XML_Char>())
        else {
            return false;
        };
        if !uri_backing(BindingUriAllocationAction::Replace {
            size,
            allocation_source_line,
            free_source_line,
        }) {
            return false;
        }
        self.uri.resize(capacity, 0);
        let binding = self.binding_mut();
        binding.uriAlloc = capacity as ::core::ffi::c_int;
        true
    }
}

unsafe fn tag_storage_new(
    parser: crate::expat_h::XML_Parser,
    source_line: ::core::ffi::c_int,
) -> Option<TagStorage> {
    let mut backing = allocation_backing(parser, ::core::mem::size_of::<TAG>(), source_line)?;
    let mut tag = Vec::new();
    if tag.try_reserve_exact(1).is_err() {
        backing(source_line);
        return None;
    }
    tag.push(TAG {
        rawName: RawNameStorage::Unset,
        rawNameLength: 0,
        name: TAG_NAME {
            str: TagNameStorage::Unset,
            localPart: None,
            strLen: 0,
            uriLen: 0,
            prefixLen: 0,
        },
        buffer: TagBufferStorage::empty(),
        bindings: None,
    });
    Some(TagStorage {
        tag,
        backing: Some(backing),
    })
}

fn release_tag_storage(active_bindings: &mut Vec<BindingStorage>, mut storage: TagStorage) {
    let tag = storage
        .tag
        .first_mut()
        .expect("tag storage always contains its allocated tag");
    tag.buffer.release(1942 as ::core::ffi::c_int);
    destroy_bindings(active_bindings, tag.bindings);
    if let Some(mut backing) = storage.backing.take() {
        backing(1944 as ::core::ffi::c_int);
    }
}
#[derive(Copy, Clone)]
#[repr(C)]

pub struct TAG_NAME {
    // Tag names either reside in the tag's allocator-backed buffer or in the
    // temporary pool used for an empty element.  An offset/reference keeps
    // that distinction explicit without retaining an address into either
    // allocation.
    pub str: TagNameStorage,
    // When namespace processing is active, this is the character offset of
    // the local part within the tag's allocator-backed name buffer.  Keeping
    // an offset rather than a pointer lets that buffer move during
    // `storeRawNames` without leaving a stale interior pointer behind.
    pub localPart: Option<usize>,
    pub strLen: ::core::ffi::c_int,
    pub uriLen: ::core::ffi::c_int,
    pub prefixLen: ::core::ffi::c_int,
}

#[derive(Copy, Clone)]
pub enum TagNameStorage {
    Unset,
    TagBuffer { offset: usize },
    TempPool(PoolStringRef),
    // The expanded namespace name remains in the active binding's
    // allocator-backed URI buffer.  Its binding is resolved from the DTD
    // when the callback needs an address, rather than retained here.
    NamespaceUri,
}
#[repr(C)]

pub struct DTD {
    pub generalEntities: HASH_TABLE,
    pub elementTypes: HASH_TABLE,
    pub attributeIds: HASH_TABLE,
    pub prefixes: HASH_TABLE,
    pub pool: STRING_POOL,
    pub entityValuePool: STRING_POOL,
    pub keepProcessing: crate::expat_h::XML_Bool,
    pub hasParamEntityRefs: crate::expat_h::XML_Bool,
    pub standalone: crate::expat_h::XML_Bool,
    pub paramEntityRead: crate::expat_h::XML_Bool,
    pub paramEntities: HASH_TABLE,
    pub defaultPrefix: PREFIX,
    pub in_eldecl: crate::expat_h::XML_Bool,
    // The content-model graph is shared when a child parser inherits its
    // parent's DTD.  Its nodes are ordinary indexed Rust storage; `backing`
    // below is retained only to preserve the observable allocation schedule
    // of the configured Expat memory suite.
    scaffold: std::sync::Arc<std::sync::Mutex<ScaffoldStorage>>,
    pub contentStringLen: ::core::ffi::c_uint,
    pub scaffSize: ::core::ffi::c_uint,
    pub scaffCount: ::core::ffi::c_uint,
    pub scaffLevel: ::core::ffi::c_int,
    pub scaffIndex: std::sync::Arc<std::sync::Mutex<Vec<::core::ffi::c_int>>>,
    // The DTD itself is Rust-owned.  This opaque token preserves the
    // configured allocator's allocation/free observation for the allocation
    // that formerly held the DTD object; it is never dereferenced.
    allocation: Option<Box<dyn FnMut(::core::ffi::c_int)>>,
}
#[derive(Copy, Clone)]
#[repr(C)]

pub struct CONTENT_SCAFFOLD {
    pub type_0: crate::expat_h::XML_Content_Type,
    pub quant: crate::expat_h::XML_Content_Quant,
    // Name scaffolds refer to a NUL-terminated value committed in the DTD
    // string pool.  The handle keeps the custom-allocator-owned block alive
    // without retaining a raw address; other scaffold kinds have no name.
    pub name: Option<PoolStringRef>,
    pub firstchild: ::core::ffi::c_int,
    pub lastchild: ::core::ffi::c_int,
    pub childcnt: ::core::ffi::c_int,
    pub nextsib: ::core::ffi::c_int,
}

// `backing` is deliberately opaque: content-model nodes live in `nodes`, but
// Expat's custom allocator still sees the same malloc/realloc/free sequence
// (and can still inject allocation failure).  Its captured allocation is
// never dereferenced or exposed to DTD state.
struct ScaffoldStorage {
    nodes: Vec<CONTENT_SCAFFOLD>,
    backing: Option<Box<dyn FnMut(ScaffoldAllocationAction) -> bool>>,
}

enum ScaffoldAllocationAction {
    Grow(usize),
    Free(::core::ffi::c_int),
}

impl ScaffoldStorage {
    fn empty() -> Self {
        Self {
            nodes: Vec::new(),
            backing: None,
        }
    }
}

fn empty_scaffold() -> std::sync::Arc<std::sync::Mutex<ScaffoldStorage>> {
    std::sync::Arc::new(std::sync::Mutex::new(ScaffoldStorage::empty()))
}
