                            let mut scaffold = (*dtd)
                                .scaffold
                                .lock()
                                .unwrap_or_else(|poisoned| poisoned.into_inner());
                            let Some(node) = scaffold.nodes.get_mut(myindex_0 as usize) else {
                                return crate::expat_h::XML_ERROR_SYNTAX;
                            };
